using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateSeeded(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1)
            };
            context.Departments.Add(dept);

            var instructor = new Instructor
            {
                ID = 1,
                LastName = "Harui",
                FirstMidName = "Roger",
                HireDate = new DateTime(1998, 7, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Gowan 27" }
            };
            context.Instructors.Add(instructor);

            dept.InstructorID = instructor.ID;

            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.Add(course);

            var ca = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(ca);

            var student = new Student
            {
                ID = 1,
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = new DateTime(2010, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            context.Students.Add(student);

            var student2 = new Student
            {
                ID = 2,
                LastName = "Alonso",
                FirstMidName = "Meredith",
                EnrollmentDate = new DateTime(2012, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            context.Students.Add(student2);

            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            };
            context.Enrollments.Add(enrollment);

            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut = new();

        public void Dispose() => _sut.Dispose();

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Student 'John Doe' has been created")]
        [InlineData(EntityOperation.UPDATE, "Student 'John Doe' has been updated")]
        [InlineData(EntityOperation.DELETE, "Student 'John Doe' has been deleted")]
        public void SendNotification_WithDisplayName_GeneratesCorrectMessage(EntityOperation op, string expectedMessage)
        {
            _sut.SendNotification("Student", "1", "John Doe", op, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal(op.ToString(), notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Student (ID: 42) has been created")]
        [InlineData(EntityOperation.UPDATE, "Student (ID: 42) has been updated")]
        [InlineData(EntityOperation.DELETE, "Student (ID: 42) has been deleted")]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage(EntityOperation op, string expectedMessage)
        {
            _sut.SendNotification("Student", "42", op, "testuser");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
        }

        [Fact]
        public void SendNotification_DefaultUserName_IsSystem()
        {
            _sut.SendNotification("Course", "100", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            var before = DateTime.Now;
            _sut.SendNotification("Course", "100", "Math", EntityOperation.CREATE, "user1");
            var after = DateTime.Now;

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Drain any leftover from other tests (static queue)
            while (_sut.ReceiveNotification() != null) { }

            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void SendAndReceive_MultipleNotifications_FifoOrder()
        {
            // Drain queue first
            while (_sut.ReceiveNotification() != null) { }

            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            var n1 = _sut.ReceiveNotification();
            var n2 = _sut.ReceiveNotification();
            var n3 = _sut.ReceiveNotification();

            Assert.Equal("A", n1!.EntityType);
            Assert.Equal("B", n2!.EntityType);
            Assert.Equal("C", n3!.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op in the in-memory implementation
            var ex = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_WithNullDisplayName_UsesIdFallback()
        {
            _sut.SendNotification("Dept", "5", null, EntityOperation.UPDATE, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("ID: 5", notification.Message);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesIdFallback()
        {
            _sut.SendNotification("Dept", "5", "  ", EntityOperation.UPDATE, "admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("ID: 5", notification.Message);
        }
    }
}

using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
        }

        [Fact]
        public void Create_MiddlePage_ReturnsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(11, result[0]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(21, result[0]);
        }

        [Theory]
        [InlineData(1, false, true)]   // first page
        [InlineData(2, true, true)]    // middle page
        [InlineData(3, true, false)]   // last page
        public void HasPreviousPage_And_HasNextPage_AreCorrect(int pageIndex, bool expectedPrev, bool expectedNext)
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex, pageSize: 10);

            Assert.Equal(expectedPrev, result.HasPreviousPage);
            Assert.Equal(expectedNext, result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_NoPrevOrNext()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Constructor_CalculatesTotalPagesCorrectly()
        {
            // 15 items, page size 4 = ceil(15/4) = 4 pages
            var list = new PaginatedList<int>(new List<int> { 1, 2, 3, 4 }, count: 15, pageIndex: 1, pageSize: 4);

            Assert.Equal(4, list.TotalPages);
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new StudentsController(_context);
            SetupController(_controller);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private static void SetupController(Controller controller)
        {
            controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            controller.TempData = new TempDataDictionary(
                controller.ControllerContext.HttpContext,
                new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        }

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Equal("Alexander", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsDescendingOrder()
        {
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Alonso", model[0].LastName);
            Assert.Equal("Alexander", model[1].LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsByEnrollmentDateAscending()
        {
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Alexander", model[0].LastName); // 2010
            Assert.Equal("Alonso", model[1].LastName);    // 2012
        }

        [Fact]
        public void Index_DateDescSort_ReturnsByEnrollmentDateDescending()
        {
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Alonso", model[0].LastName);    // 2012
            Assert.Equal("Alexander", model[1].LastName); // 2010
        }

        [Fact]
        public void Index_SearchByLastName_FiltersResults()
        {
            var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersResults()
        {
            var result = _controller.Index(null, null, "Carson", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Carson", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchStringResetsPage()
        {
            var result = _controller.Index(null, null, "Alex", null) as ViewResult;

            // When searchString is not null, page resets to 1
            Assert.NotNull(result);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            var result = _controller.Index(null, "Alexander", null, 1) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
        }

        [Fact]
        public void Details_ValidId_ReturnsStudent()
        {
            var result = _controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alexander", student.LastName);
            Assert.NotNull(student.Enrollments);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var student = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, student.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "Smith",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(3, _context.Students.Count());
        }

        [Fact]
        public void Create_Post_MinDateEnrollment_ReturnsViewWithError()
        {
