            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Equal(8, context.CourseAssignments.Count());
            Assert.True(context.Enrollments.Count() >= 11);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            var studentCountAfterFirst = context.Students.Count();

            DbInitializer.Initialize(context);
            var studentCountAfterSecond = context.Students.Count();

            Assert.Equal(studentCountAfterFirst, studentCountAfterSecond);
        }

        [Fact]
        public void Initialize_SetsUpDepartmentAdministrators()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var departments = context.Departments.ToList();
            Assert.All(departments, d => Assert.NotNull(d.InstructorID));
        }

        [Fact]
        public void Initialize_CreatesEnrollmentsWithGrades()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var enrollmentsWithGrades = context.Enrollments.Where(e => e.Grade != null).ToList();
            var enrollmentsWithoutGrades = context.Enrollments.Where(e => e.Grade == null).ToList();
            Assert.NotEmpty(enrollmentsWithGrades);
            Assert.NotEmpty(enrollmentsWithoutGrades);
        }
    }
