using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateSeeded(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1)
            };
            context.Departments.Add(dept);

            var instructor = new Instructor
            {
                ID = 1,
                LastName = "Harui",
                FirstMidName = "Roger",
                HireDate = new DateTime(1998, 7, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Gowan 27" }
            };
            context.Instructors.Add(instructor);

            dept.InstructorID = instructor.ID;

            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.Add(course);

            var ca = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(ca);

            var student = new Student
            {
                ID = 1,
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = new DateTime(2010, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            context.Students.Add(student);

            var student2 = new Student
            {
                ID = 2,
                LastName = "Alonso",
                FirstMidName = "Meredith",
                EnrollmentDate = new DateTime(2012, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            context.Students.Add(student2);

            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            };
            context.Enrollments.Add(enrollment);

            context.SaveChanges();
        }
    }
}

